
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_pbe2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_pbe2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.196097475898830e+02, 1.158555253241599e+02, 1.107110072451499e+02, 1.038077733135426e+02, 9.481650564390071e+01, 8.358526485954428e+01, 7.033762249952494e+01, 5.582850154356463e+01, 4.116423248806097e+01, 2.689868969726439e+01, 1.265613316253198e+01, 3.504483129510514e+00, 2.238214477987787e+00, 1.854813252677777e+00, 1.275653227625531e+00, 6.898382352727798e-01, 2.331167156821217e-01, 3.211250397521093e-02, 1.510418772856078e-03, 1.896452014183633e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


